package com.jnapanam.sportszone.promotion.service;
import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.identity.model.User;import com.jnapanam.sportszone.payment.model.*;import com.jnapanam.sportszone.promotion.dto.*;import com.jnapanam.sportszone.promotion.model.*;import com.jnapanam.sportszone.promotion.repository.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PromotionService{private final PromotionRepository promotions;private final PromotionRedemptionRepository redemptions;public PromotionService(PromotionRepository p,PromotionRedemptionRepository r){promotions=p;redemptions=r;}
@Transactional public PromotionResponse create(PromotionRequest r){if(promotions.findByCodeIgnoreCase(r.code()).isPresent())throw new ConflictException("Promotion code already exists");validate(r);Promotion p=new Promotion(r.code(),r.name(),r.description(),r.discountType(),r.discountValue(),r.maxDiscountPaise(),r.minOrderPaise(),r.purpose(),r.automatic(),r.onlineOnly(),r.startsAt(),r.endsAt(),r.globalUsageLimit(),r.perUserLimit());if(!r.active())apply(p,r,false);return PromotionResponse.from(promotions.save(p));}
@Transactional public PromotionResponse update(UUID id,PromotionRequest r){validate(r);Promotion p=get(id);promotions.findByCodeIgnoreCase(r.code()).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new ConflictException("Promotion code already exists");});apply(p,r,r.active());return PromotionResponse.from(p);}
@Transactional(readOnly=true)public List<PromotionResponse>all(){return promotions.findAllByOrderByCreatedAtDesc().stream().map(PromotionResponse::from).toList();}
public Applied choose(String code,long amount,PaymentPurpose purpose,User user){Instant now=Instant.now();Promotion p;if(code!=null&&!code.isBlank())p=promotions.findByCodeIgnoreCase(code.trim()).orElseThrow(()->new BadRequestException("Invalid coupon code"));else p=promotions.findByActiveTrueAndAutomaticTrueAndStartsAtLessThanEqualAndEndsAtAfter(now,now).stream().filter(x->x.eligible(amount,purpose,now)).max(Comparator.comparingLong(x->x.discount(amount))).orElse(null);if(p==null)return new Applied(null,0);if(!p.eligible(amount,purpose,now))throw new ConflictException("Promotion is not currently applicable");if(redemptions.countByPromotionIdAndUserId(p.getId(),user.getId())>=p.getPerUserLimit())throw new ConflictException("Promotion usage limit reached");return new Applied(p,p.discount(amount));}
public void redeem(Applied a,User u,PaymentOrder o){if(a.promotion()!=null&&a.discountPaise()>0){a.promotion().redeemed();redemptions.save(new PromotionRedemption(a.promotion(),u,o,a.discountPaise()));}}
private Promotion get(UUID id){return promotions.findById(id).orElseThrow(()->new NotFoundException("Promotion not found"));}private static void apply(Promotion p,PromotionRequest r,boolean active){p.update(r.code(),r.name(),r.description(),r.discountType(),r.discountValue(),r.maxDiscountPaise(),r.minOrderPaise(),r.purpose(),r.automatic(),r.onlineOnly(),r.startsAt(),r.endsAt(),r.globalUsageLimit(),r.perUserLimit(),active);}private static void validate(PromotionRequest r){if(!r.endsAt().isAfter(r.startsAt()))throw new BadRequestException("Promotion end must be after start");if(r.discountType()==DiscountType.PERCENTAGE&&r.discountValue().compareTo(java.math.BigDecimal.valueOf(100))>0)throw new BadRequestException("Percentage cannot exceed 100");}public record Applied(Promotion promotion,long discountPaise){public String code(){return promotion==null?null:promotion.getCode();}}}
